import pyomo.environ as pyo

DATA = {
    "modes": ["truck", "car"],
    "packages_per_trip": {"truck": 50, "car": 30},
    "gas_per_trip": {"truck": 20, "car": 15},
    "min_packages": 500,
    "max_truck_trips": 5,
    "min_car_share": 0.30,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.MODES = pyo.Set(initialize=d["modes"])

    # --- Variables ---
    def truck_ub(m, mode):
        if mode == "truck":
            return (0, d["max_truck_trips"])
        return (0, None)

    model.trips = pyo.Var(
        model.MODES,
        domain=pyo.NonNegativeIntegers,
        bounds=truck_ub,
    )

    # --- Objective: minimise total gas consumed ---
    def gas_rule(m):
        return sum(d["gas_per_trip"][mode] * m.trips[mode] for mode in m.MODES)

    model.obj = pyo.Objective(rule=gas_rule, sense=pyo.minimize)

    # --- Constraint: transport at least the required number of packages ---
    def packages_rule(m):
        return sum(
            d["packages_per_trip"][mode] * m.trips[mode] for mode in m.MODES
        ) >= d["min_packages"]

    model.packages_transported = pyo.Constraint(rule=packages_rule)

    # --- Constraint: at most max truck trips ---
    def truck_limit_rule(m):
        return m.trips["truck"] <= d["max_truck_trips"]

    model.truck_trip_limit = pyo.Constraint(rule=truck_limit_rule)

    # --- Constraint: at least min_car_share of all trips must be by car ---
    # trips[car] >= share * (trips[truck] + trips[car])
    # (1 - share) * trips[car] - share * trips[truck] >= 0
    def car_share_rule(m):
        share = d["min_car_share"]
        return (1 - share) * m.trips["car"] - share * m.trips["truck"] >= 0

    model.car_share = pyo.Constraint(rule=car_share_rule)

    return model


