import pyomo.environ as pyo

DATA = {
    "modes": ["truck", "car"],
    "packages_per_trip": {"truck": 50, "car": 30},
    "gas_per_trip": {"truck": 20, "car": 15},
    "min_packages": 500,
    "max_truck_trips": 5,
    "min_car_fraction": 0.30,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of transportation modes
    model.M = pyo.Set(initialize=d["modes"])

    # Decision variables: number of trips per mode (integer), truck bounded by 5
    def truck_ub(m):
        return (0, d["max_truck_trips"])

    def trip_bounds(m, i):
        if i == "truck":
            return (0, d["max_truck_trips"])
        return (0, None)

    model.trips = pyo.Var(
        model.M,
        domain=pyo.NonNegativeIntegers,
        bounds=trip_bounds,
    )

    # Objective: minimize total gas consumed
    def gas_rule(m):
        return sum(d["gas_per_trip"][i] * m.trips[i] for i in m.M)

    model.obj = pyo.Objective(expr=gas_rule, sense=pyo.minimize)

    # Constraint: transport at least min_packages packages
    def packages_rule(m):
        return sum(d["packages_per_trip"][i] * m.trips[i] for i in m.M) >= d["min_packages"]

    model.packages_required = pyo.Constraint(expr=packages_rule)

    # Constraint: at least 30% of all trips must be by car
    def car_fraction_rule(m):
        frac = d["min_car_fraction"]
        return m.trips["car"] >= frac * sum(m.trips[j] for j in m.M)

    model.car_fraction = pyo.Constraint(expr=car_fraction_rule)

    return model


